    public override double? Eval(Func<string, double?> resolve)
    {
        if (Left.Eval(resolve) is not { } a || Right.Eval(resolve) is not { } b)
            return null;
        return Op switch
        {
            '+' => a + b,
            '-' => a - b,
            '*' => a * b,
            '/' => b == 0 ? null : a / b,
            '^' => Math.Pow(a, b),
            _ => throw new InvalidOperationException($"Unknown operator {Op}"),
